#!/usr/bin/env python3
"""Compile the authored offline addon; derive guards from the supported original SO."""
import argparse,hashlib,os,subprocess,struct
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--ndk',type=Path,required=True);p.add_argument('--game',type=Path,required=True);p.add_argument('--work',type=Path,required=True);a=p.parse_args()
repo=Path(__file__).resolve().parents[1];a.work=a.work.resolve();a.work.mkdir(parents=True,exist_ok=True)
raw=a.game.read_bytes();assert hashlib.sha256(raw).hexdigest()=='733d821027d69de329d0ba171df2e6013d612edf5a4d327badd001acc30b94c7'
bin=a.ndk.resolve()/'toolchains/llvm/prebuilt/linux-x86_64/bin';src=repo/'android/test12/native';env=os.environ.copy();env['TMPDIR']=str(a.work)
subprocess.run([str(bin/'clang'),'--target=armv7a-linux-androideabi26','-marm','-Oz','-fpie','-ffreestanding','-fno-stack-protector','-fno-unwind-tables','-fno-asynchronous-unwind-tables','-nostdlib','-static','-Wl,-no-pie,-T,'+str(src/'layout.ld')+',--no-dynamic-linker,-e,patch_entry',str(src/'entry.S'),str(src/'local_crystals.c'),'-o',str(a.work/'local-crystals.elf')],check=True,env=env)
subprocess.run([str(bin/'llvm-objcopy'),'-O','binary','--only-section=.text',str(a.work/'local-crystals.elf'),str(a.work/'local-crystals.bin')],check=True)
code=(a.work/'local-crystals.bin').read_bytes();assert len(code)<0xe28
# The executable PT_LOAD has matching file offsets and RVAs for these functions.
assert struct.unpack_from('<I',raw,0xb60380)[0]==0xe92d4df0
h=14695981039346656037
for v in raw[0xb60380:0xb611a8]:h=((h^v)*1099511628211)&0xffffffffffffffff
out=repo/'core/include/zb/blockheads_crystals_code.h'
lines=['#pragma once','// Generated by tools/build_blockheads_crystals.py from our own C/assembly.','namespace zb {',f'inline constexpr unsigned long long kCrystalOriginalHash = 0x{h:016x}ULL;','inline constexpr unsigned char kCrystalCode[] = {']
lines += ['    '+','.join(f'0x{v:02x}' for v in code[i:i+16])+',' for i in range(0,len(code),16)]
lines+=['};','}  // namespace zb',''];out.write_text('\n'.join(lines));print('Authored ARM addon:',len(code),'bytes; SHA256',hashlib.sha256(code).hexdigest())
